challenges.solution_code:
CREATE TABLE customers (
  id INT,
  name VARCHAR(100),
  email VARCHAR(100),
  points INT
);

INSERT INTO customers VALUES (1, 'Alice', 'alice@example.com', 150);

SELECT name, email FROM customers WHERE points > 100;

